/**
 * Tests for MapViewportFloor component.
 */

import { describe, expect, it, vi } from 'vitest';
import { render, fireEvent, screen } from '@testing-library/react-native';
import { MapViewportFloor } from './MapViewportFloor';

const TEST_FLOOR_TARGETS = [
  { buildingId: 1, floorNumber: 1 },
  { buildingId: 1, floorNumber: 2 },
  { buildingId: 2, floorNumber: 1 },
];

const TEST_ROUTE_PATH = [
  { x: 0.5, y: 0.5, floorId: 1 },
  { x: 0.6, y: 0.4, floorId: 1 },
  { x: 0.7, y: 0.3, floorId: 2 },
];

describe('MapViewportFloor', () => {
  it('renders floor selector buttons for all targets', () => {
    const onFloorChange = vi.fn();
    render(
      <MapViewportFloor
        activeFloorId={1}
        floorTargets={TEST_FLOOR_TARGETS}
        activeFloorTarget={TEST_FLOOR_TARGETS[0]}
        routePath={TEST_ROUTE_PATH}
        onFloorChange={onFloorChange}
      />,
    );

    expect(screen.getByText('Bldg 1 Fl 1')).toBeTruthy();
    expect(screen.getByText('Bldg 1 Fl 2')).toBeTruthy();
    expect(screen.getByText('Bldg 2 Fl 1')).toBeTruthy();
  });

  it('calls onFloorChange with correct target when floor button is pressed', () => {
    const onFloorChange = vi.fn();
    render(
      <MapViewportFloor
        activeFloorId={1}
        floorTargets={TEST_FLOOR_TARGETS}
        activeFloorTarget={TEST_FLOOR_TARGETS[0]}
        routePath={TEST_ROUTE_PATH}
        onFloorChange={onFloorChange}
      />,
    );

    fireEvent.press(screen.getByText('Bldg 1 Fl 2'));
    expect(onFloorChange).toHaveBeenCalledTimes(1);
    expect(onFloorChange).toHaveBeenCalledWith({ buildingId: 1, floorNumber: 2 });
  });

  it('renders without crashing when floorTargets is empty', () => {
    const onFloorChange = vi.fn();
    const { toJSON } = render(
      <MapViewportFloor
        activeFloorId={0}
        floorTargets={[]}
        activeFloorTarget={null}
        routePath={[]}
        onFloorChange={onFloorChange}
      />,
    );

    expect(toJSON()).toBeTruthy();
  });
});

import type { NavBuilding, NavEdge, NavFloor, NavGraph, NavNode } from '../../src/shared/types';
import {
  type NavGraphContractValidationError,
  validateNavGraphPayload,
} from './navGraphSchema';
import type { PathResult, PathSegment, RouteMode } from '../../src/shared/pathfinding/types';

// Re-export pathfinding types so routing module can import everything from domain/navGraph
export type { PathResult, PathSegment, RouteMode };

/**
 * Direction generation types — turn-by-turn step generation.
 *
 * Used by mobile/routing/generateDirections.ts to convert computed paths
 * into human-readable walking instructions.
 */

/**
 * Icon types for direction step visualization.
 * Maps to icons in the mobile UI icon set.
 */
export type StepIcon =
  | 'straight'
  | 'turn-left'
  | 'turn-right'
  | 'sharp-left'
  | 'sharp-right'
  | 'arrive'
  | 'accessible'
  | 'stairs-up'
  | 'stairs-down'
  | 'elevator'
  | 'ramp';

/**
 * A single turn-by-turn direction instruction.
 */
export interface DirectionStep {
  /** Human-readable instruction, e.g. "Turn left at the cafeteria" */
  instruction: string;
  icon: StepIcon;
  /** Segment distance in normalized units (0–1 coordinate space) */
  distanceM: number;
  /** Estimated seconds for this segment */
  durationSec: number;
  /** True if this segment passes through a ramp or elevator node */
  isAccessibleSegment: boolean;
  /** Floor ID where this instruction is presented */
  floorId: number;
  /** Resolved floor number for display/grouping; falls back to floorId when metadata is missing */
  floorNumber: number;
}

/**
 * Complete result of direction generation.
 */
export interface DirectionsResult {
  steps: DirectionStep[];
  /** Sum of all segment distances in normalized units */
  totalDistanceNorm: number;
  /** Sum of all step durations in seconds */
  totalDurationSec: number;
}

/**
 * A section of directions on a single floor.
 * Used by mobile/routing/directionSections.ts for floor-grouped display.
 */
export interface DirectionSection {
  floorId: number;
  floorNumber: number;
  steps: DirectionStep[];
}

export interface NormalizedFloorRecord {
  buildingId: number;
  buildingName: string;
  floor: NavFloor;
}

export interface NormalizedNodeRecord {
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
  node: NavNode;
}

export interface NormalizedEdgeRecord {
  buildingId: number;
  floorId: number;
  edge: NavEdge;
  effectiveAccessibleWeight: number;
}

export interface NormalizedNavGraph {
  graph: NavGraph;
  buildingById: Map<number, NavBuilding>;
  floorById: Map<number, NormalizedFloorRecord>;
  floorByBuildingAndNumber: Map<string, NormalizedFloorRecord>;
  nodeById: Map<string, NormalizedNodeRecord>;
  edgeById: Map<string, NormalizedEdgeRecord>;
  outgoingEdgesByNodeId: Map<string, NormalizedEdgeRecord[]>;
}

export type NavGraphNormalizationErrorCode =
  | 'duplicate-building-id'
  | 'duplicate-floor-id'
  | 'duplicate-floor-number-per-building'
  | 'duplicate-node-id'
  | 'duplicate-edge-id'
  | 'node-floor-mismatch'
  | 'edge-node-missing';

export interface NavGraphNormalizationError {
  reason: 'normalization-failure';
  code: NavGraphNormalizationErrorCode;
  message: string;
}

export type NavGraphNormalizationResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphNormalizationError };

export type NavGraphParseAndNormalizeResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphContractValidationError | NavGraphNormalizationError };

function fail(
  code: NavGraphNormalizationErrorCode,
  message: string,
): { ok: false; error: NavGraphNormalizationError } {
  return {
    ok: false,
    error: {
      reason: 'normalization-failure',
      code,
      message,
    },
  };
}

export function floorLookupKey(buildingId: number, floorNumber: number): string {
  return `${buildingId}:${floorNumber}`;
}

export function getEffectiveAccessibleWeight(edge: Pick<NavEdge, 'accessible' | 'accessibleWeight'>): number {
  return edge.accessible ? edge.accessibleWeight : Number.POSITIVE_INFINITY;
}

export function normalizeNavGraph(graph: NavGraph): NavGraphNormalizationResult {
  const buildingById = new Map<number, NavBuilding>();
  const floorById = new Map<number, NormalizedFloorRecord>();
  const floorByBuildingAndNumber = new Map<string, NormalizedFloorRecord>();
  const nodeById = new Map<string, NormalizedNodeRecord>();
  const edgeById = new Map<string, NormalizedEdgeRecord>();
  const outgoingEdgesByNodeId = new Map<string, NormalizedEdgeRecord[]>();

  for (const building of graph.buildings) {
    if (buildingById.has(building.id)) {
      return fail('duplicate-building-id', `Duplicate building id detected: ${building.id}.`);
    }

    buildingById.set(building.id, building);

    for (const floor of building.floors) {
      if (floorById.has(floor.id)) {
        return fail('duplicate-floor-id', `Duplicate floor id detected: ${floor.id}.`);
      }

      const floorKey = floorLookupKey(building.id, floor.floorNumber);
      if (floorByBuildingAndNumber.has(floorKey)) {
        return fail(
          'duplicate-floor-number-per-building',
          `Duplicate floor number ${floor.floorNumber} for building ${building.id}.`,
        );
      }

      const floorRecord: NormalizedFloorRecord = {
        buildingId: building.id,
        buildingName: building.name,
        floor,
      };

      floorById.set(floor.id, floorRecord);
      floorByBuildingAndNumber.set(floorKey, floorRecord);

      for (const node of floor.nodes) {
        if (node.floorId !== floor.id) {
          return fail(
            'node-floor-mismatch',
            `Node ${node.id} reports floorId=${node.floorId}, expected ${floor.id}.`,
          );
        }

        if (nodeById.has(node.id)) {
          return fail('duplicate-node-id', `Duplicate node id detected: ${node.id}.`);
        }

        nodeById.set(node.id, {
          buildingId: building.id,
          buildingName: building.name,
          floorId: floor.id,
          floorNumber: floor.floorNumber,
          node,
        });
      }

      for (const edge of floor.edges) {
        if (edgeById.has(edge.id)) {
          return fail('duplicate-edge-id', `Duplicate edge id detected: ${edge.id}.`);
        }

        const edgeRecord: NormalizedEdgeRecord = {
          buildingId: building.id,
          floorId: floor.id,
          edge,
          effectiveAccessibleWeight: getEffectiveAccessibleWeight(edge),
        };

        edgeById.set(edge.id, edgeRecord);
      }
    }
  }

  for (const edgeRecord of edgeById.values()) {
    const source = nodeById.get(edgeRecord.edge.sourceId);
    const target = nodeById.get(edgeRecord.edge.targetId);

    if (!source || !target) {
      return fail(
        'edge-node-missing',
        `Edge ${edgeRecord.edge.id} references missing node(s): ${edgeRecord.edge.sourceId} -> ${edgeRecord.edge.targetId}.`,
      );
    }

    const currentOutgoing = outgoingEdgesByNodeId.get(source.node.id) ?? [];
    currentOutgoing.push(edgeRecord);
    outgoingEdgesByNodeId.set(source.node.id, currentOutgoing);
  }

  return {
    ok: true,
    data: {
      graph,
      buildingById,
      floorById,
      floorByBuildingAndNumber,
      nodeById,
      edgeById,
      outgoingEdgesByNodeId,
    },
  };
}

export function parseAndNormalizeNavGraph(payload: unknown): NavGraphParseAndNormalizeResult {
  const validated = validateNavGraphPayload(payload);
  if (!validated.ok) {
    return validated;
  }

  return normalizeNavGraph(validated.data);
}

/**
 * Tests for useRouteSession hook.
 *
 * Covers:
 * - idle state when no selection
 * - computing→ready on valid route
 * - no-route when unreachable
 * - error state for invalid nodes
 * - accessible mode filtering
 */

import { describe, expect, it, vi } from 'vitest';
import { renderHook } from '@testing-library/react';
import type { NavBuilding, NavFloor, NavGraph } from '../../src/shared/types';
import { useRouteSession } from './useRouteSession';
import { normalizeNavGraph } from '../domain/navGraph';

/** Build a minimal two-room graph on a single floor with one connecting edge. */
function createTestNavGraph(): NavGraph {
  const building: NavBuilding = {
    id: 1,
    name: 'Test Building',
    abbreviation: 'TB',
    floors: [
      {
        id: 1,
        buildingId: 1,
        floorNumber: 1,
        name: 'Floor 1',
        level: 1,
        svgPath: '',
        nodes: [
          {
            id: 'room-a',
            x: 0.1,
            y: 0.5,
            floorId: 1,
            type: 'room',
            searchable: true,
            label: 'Room A',
            roomNumber: 'A101',
          },
          {
            id: 'room-b',
            x: 0.9,
            y: 0.5,
            floorId: 1,
            type: 'room',
            searchable: true,
            label: 'Room B',
            roomNumber: 'B101',
          },
        ],
        edges: [
          {
            id: 'edge-a-b',
            sourceId: 'room-a',
            targetId: 'room-b',
            standardWeight: 0.8,
            accessibleWeight: 0.8,
            accessible: true,
            bidirectional: true,
          },
        ],
      },
    ],
  };

  return { buildings: [building] };
}

/** Build a graph with a disconnected component (no route between room-a and room-c). */
function createDisconnectedNavGraph(): NavGraph {
  const building: NavBuilding = {
    id: 1,
    name: 'Test Building',
    abbreviation: 'TB',
    floors: [
      {
        id: 1,
        buildingId: 1,
        floorNumber: 1,
        name: 'Floor 1',
        level: 1,
        svgPath: '',
        nodes: [
          { id: 'room-a', x: 0.1, y: 0.5, floorId: 1, type: 'room', searchable: true, label: 'Room A', roomNumber: 'A101' },
          { id: 'room-b', x: 0.9, y: 0.5, floorId: 1, type: 'room', searchable: true, label: 'Room B', roomNumber: 'B101' },
        ],
        edges: [
          { id: 'edge-a-b', sourceId: 'room-a', targetId: 'room-b', standardWeight: 0.8, accessibleWeight: 0.8, accessible: true, bidirectional: true },
        ],
      },
      {
        id: 2,
        buildingId: 1,
        floorNumber: 2,
        name: 'Floor 2',
        level: 2,
        svgPath: '',
        nodes: [
          { id: 'room-c', x: 0.5, y: 0.5, floorId: 2, type: 'room', searchable: true, label: 'Room C', roomNumber: 'C101' },
        ],
        edges: [],
      },
    ],
  };

  return { buildings: [building] };
}

/** Build a graph with a stairs-only inter-floor connection (blocked in accessible mode). */
function createStairsOnlyNavGraph(): NavGraph {
  const building: NavBuilding = {
    id: 1,
    name: 'Test Building',
    abbreviation: 'TB',
    floors: [
      {
        id: 1,
        buildingId: 1,
        floorNumber: 1,
        name: 'Floor 1',
        level: 1,
        svgPath: '',
        nodes: [
          { id: 'room-f1', x: 0.1, y: 0.5, floorId: 1, type: 'room', searchable: true, label: 'Room F1', roomNumber: 'F101' },
          {
            id: 'stairs-1',
            x: 0.9,
            y: 0.5,
            floorId: 1,
            type: 'stairs',
            searchable: false,
            label: 'Stairs',
            connectsToNodeAboveId: 'stairs-2',
            connectsToFloorAboveId: 2,
            connectsToNodeBelowId: undefined,
            connectsToFloorBelowId: undefined,
          },
        ],
        edges: [
          { id: 'edge-f1-stairs', sourceId: 'room-f1', targetId: 'stairs-1', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true },
        ],
      },
      {
        id: 2,
        buildingId: 1,
        floorNumber: 2,
        name: 'Floor 2',
        level: 2,
        svgPath: '',
        nodes: [
          { id: 'room-f2', x: 0.9, y: 0.5, floorId: 2, type: 'room', searchable: true, label: 'Room F2', roomNumber: 'F201' },
          {
            id: 'stairs-2',
            x: 0.9,
            y: 0.5,
            floorId: 2,
            type: 'stairs',
            searchable: false,
            label: 'Stairs',
            connectsToNodeBelowId: 'stairs-1',
            connectsToFloorBelowId: 1,
            connectsToNodeAboveId: undefined,
            connectsToFloorAboveId: undefined,
          },
        ],
        edges: [
          { id: 'edge-f2-stairs', sourceId: 'room-f2', targetId: 'stairs-2', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true },
        ],
      },
    ],
  };

  return { buildings: [building] };
}

function makeNavNode(id: string, label: string): import('../../src/shared/types').NavNode {
  return {
    id,
    x: 0.5,
    y: 0.5,
    floorId: 1,
    type: 'room',
    searchable: true,
    label,
  };
}

// ============================================================
// Tests
// ============================================================

describe('useRouteSession', () => {
  describe('idle state', () => {
    it('returns idle phase when no start is set', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: null, destination: makeNavNode('room-b', 'Room B') },
        }),
      );

      expect(result.current.sessionState.phase).toBe('idle');
    });

    it('returns idle phase when no destination is set', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: makeNavNode('room-a', 'Room A'), destination: null },
        }),
      );

      expect(result.current.sessionState.phase).toBe('idle');
    });

    it('returns idle phase when both are null', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: null, destination: null },
        }),
      );

      expect(result.current.sessionState.phase).toBe('idle');
    });
  });

  describe('ready state', () => {
    it('returns ready phase when both start and destination are valid and reachable', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: makeNavNode('room-a', 'Room A'), destination: makeNavNode('room-b', 'Room B') },
        }),
      );

      expect(result.current.sessionState.phase).toBe('ready');
      const state = result.current.sessionState;
      if (state.phase !== 'ready') throw new Error('Expected ready state');
      expect(state.path.found).toBe(true);
      expect(state.directions.steps.length).toBeGreaterThan(0);
    });

    it('path result contains correct node IDs', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: makeNavNode('room-a', 'Room A'), destination: makeNavNode('room-b', 'Room B') },
        }),
      );

      const state = result.current.sessionState;
      if (state.phase !== 'ready') throw new Error('Expected ready state');
      expect(state.path.nodeIds).toContain('room-a');
      expect(state.path.nodeIds).toContain('room-b');
    });

    it('directions result contains arrive step', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: makeNavNode('room-a', 'Room A'), destination: makeNavNode('room-b', 'Room B') },
        }),
      );

      const state = result.current.sessionState;
      if (state.phase !== 'ready') throw new Error('Expected ready state');
      const arriveSteps = state.directions.steps.filter(s => s.icon === 'arrive');
      expect(arriveSteps.length).toBe(1);
    });
  });

  describe('no-route state', () => {
    it('returns no-route when start and destination are in disconnected components', () => {
      const graph = normalizeNavGraph(createDisconnectedNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: makeNavNode('room-a', 'Room A'), destination: makeNavNode('room-c', 'Room C') },
        }),
      );

      expect(result.current.sessionState.phase).toBe('no-route');
    });
  });

  describe('error state', () => {
    it('returns error when start node is not in the graph', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: {
            start: makeNavNode('unknown-node', 'Unknown'),
            destination: makeNavNode('room-b', 'Room B'),
          },
        }),
      );

      expect(result.current.sessionState.phase).toBe('error');
      const state = result.current.sessionState;
      if (state.phase !== 'error') throw new Error('Expected error state');
      expect(state.errorMessage).toContain('not present');
    });

    it('returns error when destination node is not in the graph', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: {
            start: makeNavNode('room-a', 'Room A'),
            destination: makeNavNode('unknown-dest', 'Unknown'),
          },
        }),
      );

      expect(result.current.sessionState.phase).toBe('error');
    });
  });

  describe('accessible mode', () => {
    it('returns ready with accessible mode when stairs-only path is blocked', () => {
      const graph = normalizeNavGraph(createStairsOnlyNavGraph()).data!;

      // First verify standard mode works (should find route via stairs)
      const { result: standardResult } = renderHook(() =>
        useRouteSession({
          graph,
          selection: {
            start: makeNavNode('room-f1', 'Room F1'),
            destination: makeNavNode('room-f2', 'Room F2'),
          },
        }),
      );
      expect(standardResult.current.sessionState.phase).toBe('ready');

      // Accessible mode should block stairs and return no-route
      const { result: accessibleResult } = renderHook(() => {
        const { useRouteSession: _useRouteSession } = require('./useRouteSession');
        // Use routeMode: 'accessible' by setting it before the hook
        return { current: null };
      });

      // Direct test via computeRouteSession
      const { computeRouteSession } = require('./routeSessionState');
      const standardSession = computeRouteSession({
        graph,
        mode: 'standard',
        start: makeNavNode('room-f1', 'Room F1'),
        destination: makeNavNode('room-f2', 'Room F2'),
      });
      expect(standardSession.phase).toBe('ready');

      const accessibleSession = computeRouteSession({
        graph,
        mode: 'accessible',
        start: makeNavNode('room-f1', 'Room F1'),
        destination: makeNavNode('room-f2', 'Room F2'),
      });
      expect(accessibleSession.phase).toBe('no-route');
    });
  });

  describe('routeMode state', () => {
    it('exposes routeMode and setRouteMode', () => {
      const graph = normalizeNavGraph(createTestNavGraph()).data!;
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: null, destination: null },
        }),
      );

      expect(result.current.routeMode).toBe('standard');
      result.current.setRouteMode('accessible');
      expect(result.current.routeMode).toBe('accessible');
    });
  });
});

/**
 * Core navigation graph type definitions for CampusNav.
 *
 * Two categories of types:
 *
 * 1. **ngraph.graph data types** — `NavNodeData` and `NavEdgeData` are the `.data`
 *    fields stored on ngraph.graph's Node and Link objects via
 *    `graph.addNode(id, data)` and `graph.addLink(from, to, data)`.
 *
 * 2. **Serialization types** — `NavNode`, `NavEdge`, `NavFloor`, `NavBuilding`,
 *    and `NavGraph` are the JSON shapes used for API transport (GET /api/map) and
 *    file storage. The client loads a `NavGraph`, iterates `buildings[].floors[]`,
 *    destructures each node/edge into `(id, data)`, and feeds them into ngraph.graph.
 *    `NavNode` objects live inside `NavFloor.nodes[]`.
 *
 * All coordinates are **NORMALIZED** (0.0–1.0), representing percentages of the
 * floor plan image dimensions. Convert to pixels only at render time:
 * `pixelX = node.x * canvasWidth`.
 */

// ============================================================
// Node Types
// ============================================================

/**
 * Classification of navigation nodes on a floor plan.
 *
 * **Visible to students** (searchable destinations):
 * - `room` — Classroom, office, lab
 * - `entrance` — Building entrance/exit
 * - `elevator` — Elevator (also an accessibility waypoint)
 * - `restroom` — Restroom
 * - `landmark` — Named point of interest (cafeteria, library)
 *
 * **Invisible to students** (routing infrastructure only):
 * - `stairs` — Stairwell navigation waypoint, HIDDEN from student map (routing infrastructure only)
 * - `ramp` — Ramp navigation waypoint, HIDDEN from student map (routing infrastructure only)
 * - `junction` — Hallway intersection
 * - `hallway` — Mid-hallway point
 */
export type NavNodeType =
  | 'room'
  | 'entrance'
  | 'elevator'
  | 'stairs'
  | 'ramp'
  | 'restroom'
  | 'junction'
  | 'hallway'
  | 'landmark'

/**
 * Data stored on each graph node (the `.data` field of an ngraph.graph Node).
 *
 * Coordinates are normalized 0.0–1.0: percentage of floor plan width/height.
 */
export interface NavNodeData {
  /** Normalized x position (0.0 = left edge, 1.0 = right edge of floor plan) */
  x: number
  /** Normalized y position (0.0 = top edge, 1.0 = bottom edge of floor plan) */
  y: number
  /** Display label for search results and turn-by-turn directions */
  label: string
  /** Node classification — determines visibility and search behavior */
  type: NavNodeType
  /** Whether this node appears in student search results */
  searchable: boolean
  /** ID of the floors record this node belongs to (FK → floors.id) */
  floorId: number
  // buildingName REMOVED — derived transitively via floor → building
  /** Room/office number identifier (e.g. "204", "A-102") */
  roomNumber?: string
  /** Human-readable description shown in location detail sheet */
  description?: string
  /** Accessibility information shown in detail sheet */
  accessibilityNotes?: string
  // Floor connector linkage — only set on stairs, elevator, ramp nodes
  /** ID of the floor above that this connector node links to */
  connectsToFloorAboveId?: number
  /** ID of the floor below that this connector node links to */
  connectsToFloorBelowId?: number
  /** ID of the corresponding node on the floor above */
  connectsToNodeAboveId?: string
  /** ID of the corresponding node on the floor below */
  connectsToNodeBelowId?: string
  /** ID of the building this campus entrance marker bridges to (campus map only, entrance nodes) */
  connectsToBuildingId?: number
}

// ============================================================
// Edge Types
// ============================================================

/**
 * Data stored on each graph edge (the `.data` field of an ngraph.graph Link).
 *
 * Every edge carries **dual weights** to enable accessibility routing:
 * - `standardWeight`: cost for the standard walking route
 * - `accessibleWeight`: cost for the wheelchair-accessible route
 *   (same as standard for flat paths; higher for detours like ramps;

[121 more lines in file. Use offset=101 to continue.]

 *   `Infinity` for non-accessible edges like stairs)
 */
export interface NavEdgeData {
  /**
   * Walking cost for the standard route.
   * Typically the Euclidean distance between connected nodes in normalized
   * coordinates. Can be overridden by an admin for non-straight paths.
   */
  standardWeight: number
  /**
   * Walking cost for the wheelchair-accessible route.
   * - Same as `standardWeight` for accessible paths.
   * - Higher than `standardWeight` if the accessible path is longer (e.g. ramp).
   * - `Infinity` for non-accessible edges (e.g. stairs without elevator).
   */
  accessibleWeight: number
  /** Whether this edge is traversable by wheelchair */
  accessible: boolean
  /** Whether this edge can be traversed in both directions */
  bidirectional: boolean
  /** Optional admin notes ("3 steps", "narrow doorway", "automatic door") */
  accessibilityNotes?: string
}

// ============================================================
// Serialization Types (API / JSON transport)
// ============================================================

/**
 * A serialized node for JSON transport (API responses, file storage).
 * Combines the node's unique ID with its data fields.
 * NavNode inherits `floorId` from NavNodeData — no direct change needed.
 */
export interface NavNode extends NavNodeData {
  /** Unique identifier for this node (e.g. "room-204", "entrance-main") */
  id: string
}

/**
 * A serialized edge for JSON transport (API responses, file storage).
 * Combines the edge's ID, endpoint references, and data fields.
 */
export interface NavEdge extends NavEdgeData {
  /** Unique identifier for this edge */
  id: string
  /** Source node ID */
  sourceId: string
  /** Target node ID */
  targetId: string
}

/**
 * Optional real-world GPS bounds used to project normalized floor coordinates
 * onto latitude/longitude space.
 */
export interface NavFloorGpsBounds {
  /** Minimum latitude represented by this floor map */
  minLat: number
  /** Maximum latitude represented by this floor map */
  maxLat: number
  /** Minimum longitude represented by this floor map */
  minLng: number
  /** Maximum longitude represented by this floor map */
  maxLng: number
}

/**
 * A single floor within a building, containing all nodes and edges on that floor.
 */
export interface NavFloor {
  /** Database ID of this floor record (floors.id) */
  id: number
  /** Floor number (1-based) */
  floorNumber: number
  /** Path to the floor plan image asset */
  imagePath: string
  /** ISO 8601 timestamp of last graph modification */
  updatedAt: string
  /** Optional GPS calibration bounds for this floor */
  gpsBounds?: NavFloorGpsBounds
  /** All navigation nodes on this floor */
  nodes: NavNode[]
  /** All navigation edges on this floor */
  edges: NavEdge[]
}

/**
 * A building containing one or more floors.
 */
export interface NavBuilding {
  /** Database ID of this building record (buildings.id) */
  id: number
  /** Display name of the building */
  name: string
  /** All floors within this building */
  floors: NavFloor[]
}

/**
 * Complete navigation graph as JSON — returned by `GET /api/map`.
 *
 * The client loads this on page init and builds an ngraph.graph instance
 * by iterating the nested buildings → floors → nodes/edges structure:
 * ```ts
 * const graph = createGraph<NavNodeData, NavEdgeData>()
 * for (const building of navGraph.buildings) {
 *   for (const floor of building.floors) {
 *     for (const { id, ...data } of floor.nodes) graph.addNode(id, data)
 *     for (const { id, sourceId, targetId, ...data } of floor.edges)
 *       graph.addLink(sourceId, targetId, data)
 *   }
 * }
 * ```
 */
export interface NavGraph {
  /** All buildings in the campus, each containing floors with nodes and edges */
  buildings: NavBuilding[]
  // nodes and edges now live under buildings[].floors[].nodes/edges
  // metadata replaced by floors[].updatedAt
}

