content.text:
/**
 * MapViewportFloor — floor-switching extension of MapViewport.
 *
 * Composes:
 * - MapViewport (floor plan image with pan/pinch/rotate controls)
 * - Floor selector strip (horizontal ScrollView of floor buttons)
 * - RoutePathOverlay (polyline overlay on active floor)
 *
 * The active floor target is tracked in state and drives both
 * which image is shown and which floor segment is rendered.
 */

import { useCallback, useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { MapViewport } from './MapViewport';
import { RoutePathOverlay, type RoutePathPoint } from '../components/route/RoutePathOverlay';
import type { FloorPlanTarget } from '../data/mapApiClient';
import type { MapTransform } from './mapTransform';
import type { ViewportDimensions } from './mapTransform';

/* ─── Props ─── */

export interface MapViewportFloorProps {
  /** MapViewport props */
  onTransformChange?: (transform: MapTransform) => void;
  /** All available floor targets for the active route */
  floorTargets: FloorPlanTarget[];
  /** Currently selected floor target */
  activeFloorTarget: FloorPlanTarget | null;
  /** Floor ID for the active target (used for route path overlay filtering) */
  activeFloorId: number;
  /** Route path waypoints (normalized coordinates) */
  routePath: RoutePathPoint[];
  /** Called when user presses a floor button */
  onFloorChange: (target: FloorPlanTarget) => void;
  /** Whether to show the route path overlay */
  showRouteOverlay?: boolean;
  /** Whether to show the floor selector strip */
  showFloorSelector?: boolean;
}

/* ─── State ─── */

interface FloorButtonData {
  target: FloorPlanTarget;
  label: string;
  isActive: boolean;
}

/* ─── Component ─── */

export function MapViewportFloor({
  onTransformChange,
  floorTargets,
  activeFloorTarget,
  activeFloorId,
  routePath,
  onFloorChange,
  showRouteOverlay = true,
  showFloorSelector = true,
}: MapViewportFloorProps) {
  const [transform, setTransform] = useState<MapTransform>({
    scale: 1,
    rotationDeg: 0,
    translation: { x: 0, y: 0 },
  });
  const [viewportDimensions, setViewportDimensions] = useState<ViewportDimensions>({ width: 300, height: 300 });

  const handleTransformChange = useCallback(
    (t: MapTransform) => {
      setTransform(t);
      onTransformChange?.(t);
    },
    [onTransformChange],
  );

  // Build floor button data
  const floorButtons: FloorButtonData[] = floorTargets.map(target => ({
    target,
    label: `Bldg ${target.buildingId} Fl ${target.floorNumber}`,
    isActive: activeFloorTarget !== null
      && activeFloorTarget.buildingId === target.buildingId
      && activeFloorTarget.floorNumber === target.floorNumber,
  }));

  return (
    <View style={styles.container}>
      {/* Map viewport with optional route overlay */}
      <View style={styles.mapContainer}>
        <MapViewport
          imageUri=""
          onTransformChange={handleTransformChange}
        />
        {showRouteOverlay && activeFloorTarget && (
          <RoutePathOverlay
            path={routePath}
            activeFloorId={activeFloorId}
            viewport={viewportDimensions}
            scale={transform.scale}
          />
        )}
      </View>

      {/* Floor selector strip */}
      {showFloorSelector && floorButtons.length > 0 && (
        <View style={styles.floorSelector}>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.floorScrollContent}
          >
            {floorButtons.map((btn, idx) => (
              <Pressable
                key={`floor-${idx}`}
                style={[styles.floorButton, btn.isActive && styles.floorButtonActive]}
                onPress={() => onFloorChange(btn.target)}
              >
                <Text style={[styles.floorButtonText, btn.isActive && styles.floorButtonTextActive]}>
                  {btn.label}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
        </View>
      )}
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  container: {
    width: '100%',
    gap: 8,
  },
  mapContainer: {
    flex: 1,
    minHeight: 280,
    borderRadius: 12,
    overflow: 'hidden',
  },
  floorSelector: {
    paddingVertical: 4,
  },
  floorScrollContent: {
    flexDirection: 'row',
    gap: 8,
    paddingHorizontal: 4,
    paddingVertical: 4,
  },
  floorButton: {
    backgroundColor: '#0f172a',
    borderColor: '#334155',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  floorButtonActive: {
    backgroundColor: '#0c2d4a',
    borderColor: '#38bdf8',
    borderWidth: 1.5,
  },
  floorButtonText: {
    color: '#94a3b8',
    fontSize: 12,
    fontWeight: '500',
  },
  floorButtonTextActive: {
    color: '#38bdf8',
    fontWeight: '700',
  },
});

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'jsdom',
    globals: true,
    include: ['**/*.test.ts', '**/*.test.tsx'],
    exclude: ['**/node_modules/**', '**/.git/**'],
    clearMocks: true,
    restoreMocks: true,
  },
});

/**
 * RoutePathOverlay — renders the computed route path on top of the floor plan image.
 *
 * View-based polyline (no new SVG dependency). For each adjacent pair of
 * nodes on the active floor, renders endpoint dots and a connecting line
 * rotated to match the bearing.
 */

import { StyleSheet, View } from 'react-native';
import type { ViewportDimensions } from '../../map/mapTransform';

/* ─── Types ─── */

export interface RoutePathPoint {
  x: number;       // normalized [0,1]
  y: number;       // normalized [0,1]
  floorId: number;
}

interface Props {
  path: RoutePathPoint[];
  activeFloorId: number;
  viewport: ViewportDimensions;
  scale: number;
}

/* ─── Helpers (pure, no closure state) ─── */

function segmentBearingDeg(
  from: RoutePathPoint,
  to: RoutePathPoint,
  vp: ViewportDimensions,
  sc: number,
): number {
  const dx = (to.x - from.x) * vp.width * sc;
  const dy = (to.y - from.y) * vp.height * sc;
  return Math.atan2(dy, dx) * (180 / Math.PI);
}

function segmentLen(
  from: RoutePathPoint,
  to: RoutePathPoint,
  vp: ViewportDimensions,
  sc: number,
): number {
  const dx = (to.x - from.x) * vp.width * sc;
  const dy = (to.y - from.y) * vp.height * sc;
  return Math.hypot(dx, dy);
}

/* ─── Coordinate to pixel position ─── */

function toPixel(node: RoutePathPoint, vp: ViewportDimensions, sc: number) {
  return {
    left: node.x * vp.width * sc - 4,
    top:  node.y * vp.height * sc - 4,
  };
}

/* ─── Component ─── */

export function RoutePathOverlay({ path, activeFloorId, viewport, scale }: Props) {
  const floorNodes = path.filter(n => n.floorId === activeFloorId);

  if (floorNodes.length === 0) return null;

  // Single node → draw one dot
  if (floorNodes.length === 1) {
    const { left, top } = toPixel(floorNodes[0], viewport, scale);
    return <View style={[styles.dot, styles.dotStart, { left, top }]} />;
  }

  // Multiple nodes → draw start/end dots + connecting segments
  return (
    <View style={styles.overlay} pointerEvents="none">
      {/* Start dot */}
      <View style={[styles.dot, styles.dotStart, toPixel(floorNodes[0], viewport, scale)]} />

      {/* Segments between consecutive nodes */}
      {floorNodes.slice(1).map((toNode, i) => {
        const fromNode = floorNodes[i];
        const { left: startLeft, top: startTop } = toPixel(fromNode, viewport, scale);
        const { left: endLeft, top: endTop } = toPixel(toNode, viewport, scale);
        const len = segmentLen(fromNode, toNode, viewport, scale);
        const angleDeg = segmentBearingDeg(fromNode, toNode, viewport, scale);

        return (
          <View key={`seg-${i}`} style={styles.overlay} pointerEvents="none">
            {/* Connecting line (anchored at start, rotated) */}
            {len > 0 && (
              <View
                style={[
                  styles.line,
                  { width: len, left: startLeft + 4, top: startTop + 3, transform: [{ rotate: `${angleDeg}deg` }] },
                ]}
              />
            )}
          </View>
        );
      })}

      {/* End dot */}
      <View style={[styles.dot, styles.dotEnd, toPixel(floorNodes[floorNodes.length - 1], viewport, scale)]} />
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  overlay: {
    ...StyleSheet.absoluteFillObject,
  },
  dot: {
    position: 'absolute',
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: '#38bdf8',
  },
  dotStart: {
    backgroundColor: '#4ade80',
  },
  dotEnd: {
    backgroundColor: '#f87171',
  },
  line: {
    position: 'absolute',
    height: 2,
    backgroundColor: '#38bdf8',
    transformOrigin: 'left center',
  },
});
